import { Bell, ChevronDown, Mail, Menu, Plus, Search } from 'lucide-react'
export default function VendorHeader({ query, onQueryChange }) { return <header className="vendor-header"><button className="vendor-menu" type="button"><Menu size={20} /></button><label><Search size={18} /><input value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder="Search products, orders, customers..." /><kbd>⌘ K</kbd></label><div><button type="button" className="vendor-alert"><Bell size={20} /><b>6</b></button><button type="button" className="vendor-alert"><Mail size={20} /><b>3</b></button><button type="button" className="vendor-add"><Plus size={18} />Add New⌄</button><span className="vendor-avatar">N</span><p><strong>Nila Naturals</strong><small>Vendor</small></p><ChevronDown size={16} /></div></header> }
